370	// ---- flow: redirects -----------------------------------------------------------------
371	
372	// redirectFlow sends the request and follows the redirects it can.
373	func (r *recorder) redirectFlow(ctx context.Context, j recordJob, rq replayRequest) ([]replayStep, string, error) {
374		var steps []replayStep
375		for hops := 0; ; hops++ {
376			s, err := r.send(ctx, j, rq, "")
377			if err != nil {
378				return nil, "", err
379			}
380			steps = append(steps, s)
381			location := s.raw.Header.Get("Location")
382			if location == "" || !slices.Contains(redirectCodes, s.raw.Status) {
383				return steps, "", nil
384			}
385			if hops == maxRedirectHops {
386				return nil, "", recordError("the answer to "+j.name+" redirects more than "+strconv.Itoa(maxRedirectHops)+" times",
387					"do not record a chain that does not end", nil)
388			}
389			next, note := r.redirectedRequest(j, rq, location)
390			if note != "" {
391				return steps, note, nil
392			}
393			rq = next
394		}
395	}
396	
397	// redirectedRequest is the request a Location asks for: a relative one is resolved
398	// against the request that was redirected. It is empty, with the note that says
399	// why, unless the target is an origin of the run and a request the recorder sends.
400	func (r *recorder) redirectedRequest(j recordJob, from replayRequest, location string) (replayRequest, string) {
401		base, err := url.Parse("http://" + from.host + from.target)
402		if err != nil {
403			return replayRequest{}, noteRedirect
404		}
405		ref, err := url.Parse(location)
406		if err != nil {
407			return replayRequest{}, noteRedirect
408		}
409		u := base.ResolveReference(ref)
410		if _, known := r.o.Origins[u.Host]; !known || u.User != nil || (u.Scheme != "http" && u.Scheme != "https") {
411			return replayRequest{}, noteRedirect
412		}
413		next := replayRequest{method: from.method, target: u.RequestURI(), host: u.Host, header: from.header}
414		ex := nexusfixture.Exchange{Method: next.method, Target: next.target, Host: next.host}
415		if reason, _ := refusedFixtureRequest(ex, j.current.Meta, r.restHost, r.o.AllowCacheEffects); reason != "" {
416			return replayRequest{}, noteRedirectList
417		}
418		return next, ""
419	}
