20	// The replay of the jobs of a run and the flows of a fixture (DEVDESK-580, PR2).
21	//
22	// A fixture that says "flow: bearer" or "flow: redirects" holds several exchanges
23	// and the recorder follows them as DevDesk would, within limits:
24	//
25	//   - bearer: the first request goes out as DevDesk sends it. On a 401 with a Bearer
26	//     challenge whose realm is an origin of RecordOptions.Origins (matched on
27	//     host:port) and a token path, the token is asked for with the credentials of the
28	//     identity and the first request is sent again with it: three exchanges. Any
29	//     other realm ends the flow, nothing is sent to it. The token read is a term no
30	//     file and no output may hold;
31	//   - redirects: a 3xx whose Location is an origin of Origins and a request the
32	//     closed list allows is followed, 5 hops at most, each hop with the credentials
33	//     of the first request; any other Location is recorded and not followed.
34	//
35	// A reason to stop short is written in the file, in the parentheses of the "nexus"
36	// header, which the recorder rewrites on every run.
37	
38	const (
39		// maxRedirectHops is how many redirects a chain may hold before it is an error.
40		maxRedirectHops = 5
41	
42		noteRealm        = "realm off-origin, not followed"
43		noteNoChallenge  = "no challenge"
44		noteNoBearer     = "no Bearer challenge"
45		noteTokenRefused = "token refused, not retried"
46		noteRedirect     = "off-origin redirect, not followed"
47		noteRedirectList = "redirect to a request outside the closed list, not followed"
48	
49		// tokenAccept is the Accept header of a token request.
50		tokenAccept = "application/json"
51	)
52	
53	var (
54		challengeParam = regexp.MustCompile(`([A-Za-z_]+)="([^"]*)"`)
55		redirectCodes  = []int{http.StatusMovedPermanently, http.StatusFound, http.StatusSeeOther, http.StatusTemporaryRedirect, http.StatusPermanentRedirect}
56	)
57	
58	// recorder is the state of one run of the jobs: its clients, one per origin and
59	// identity, and the terms no output may hold.
60	type recorder struct {
61		o        RecordOptions
62		restHost string
63		timeout  time.Duration
64		clients  map[string]*client
65		// terms are the bench passwords and the deny list, then every token read by a flow.
66		terms []string
67		// cacheEffects are the fixtures sent with "effect: caches", in the order sent.
68		cacheEffects []string
69	}
70	
71	func newRecorder(o RecordOptions) *recorder {
72		restHost, _ := restOriginKey(o.Descriptor)
73		return &recorder{
74			o: o, restHost: restHost, timeout: recordRequestTimeout(o),
75			clients: map[string]*client{}, terms: recordTerms(o),
76		}
77	}
78	
79	func (r *recorder) close() {
80		for _, c := range r.clients {
81			c.closeIdle()
82		}
83	}
84	
85	// client returns the client of an origin for the identity of the job.
86	func (r *recorder) client(j recordJob, base string) *client {
87		key := base + "\x00" + string(j.current.Identity)
88		c, ok := r.clients[key]
89		if !ok {
90			c = newClient(base, j.user, j.password)
91			c.setTimeout(r.timeout)
92			r.clients[key] = c
93		}
94		return c
95	}
