174	// termsWithout is the list of forbidden terms but the token an answer carries on purpose.
175	func (r *recorder) termsWithout(issued string) []string {
176		if issued == "" {
177			return r.terms
178		}
179		return slices.DeleteFunc(slices.Clone(r.terms), func(t string) bool { return t == issued })
180	}
