192	// sameAnswer reports whether the file already holds the answers: the same
193	// exchanges, all of them, under the same version and edition. The date, the notes
194	// and who recorded it do not count.
195	func sameAnswer(current, recorded nexusfixture.Fixture) bool {
196		if current.Meta.NexusVersion != recorded.Meta.NexusVersion || current.Meta.Edition != recorded.Meta.Edition ||
197			len(current.Exchanges) != len(recorded.Exchanges) {
198			return false
199		}
200		text := func(ex nexusfixture.Exchange) []byte {
201			return nexusfixture.Format(nexusfixture.Fixture{Exchanges: []nexusfixture.Exchange{ex}})
202		}
203		for i := range current.Exchanges {
204			if !bytes.Equal(text(current.Exchanges[i]), text(recorded.Exchanges[i])) {
205				return false
206			}
207		}
208		return true
209	}
